agent.registerScheduleTrigger("Execute RL-1 New runlist every 3 minutes on weekdays", {
    timezone: "Asia/Kolkata",
    scheduleKind: "recurring",
    oneTime: null,
    recurring: {
        dayScope: "weekdays",
        includedDays: [],
        windowStartTime: "00:00",
        windowEndTime: "23:59",
        intervalValue: 3,
        intervalUnit: "minutes"
    }
}, async (context) => {
    const __agentHandlerResult = await (async () => {
        const scopeConversationId = "";
        const scopeLatestUserMessage = "Start an execution of the existing runlist RL-1 New runlist in the current team.";
        const scopeSelectedOptionText = "";
        const scopeInteractiveBrowserAvailable = false;
        const scopeRequestedBrowserHostId = undefined;
        const scopeRequestedClientUserId = undefined;
        const scopeRequestedClientHomeAccountId = undefined;
        const scopeCurrentUserId = "57";
        const scopeTeamId = "6007";
        const scopeOwnerAssetId = "35115";
        const scopeActiveAssetId = "35115";
        const scopeActiveAssetType = "agent";
        const scopeActiveAssetDisplayId = "AG-3";
        const scopeActiveAssetName = "New agent";
        const scopeCurrentTeamAssetId = "16348";
        const scopeCurrentFolderAssetId = undefined;
        const scopeDefaultCreateParentAssetId = "16348";
        const scopeResolvedBlueprintGeneratorAssetId = "24858";
        const scopeResolvedKnowledgeBaseAssetId = "18261";

        const uiIntents = [];

        const runlistSearch = await context.assets.search({
          text: "RL-1",
          filter: {
            types: ["runlist"],
            teamId: scopeTeamId,
            names: ["New runlist"]
          },
          limit: 10
        });

        let runlist = runlistSearch.items.find(
          (asset) =>
            asset.type === "runlist" &&
            asset.teamId === scopeTeamId &&
            (asset.displayId === "RL-1" || asset.name === "New runlist")
        );

        if (!runlist) {
          const match = await context.assets.findByText({
            text: "New runlist",
            types: ["runlist"],
            teamId: scopeTeamId
          });

          if (
            match &&
            match.id &&
            match.type === "runlist" &&
            match.teamId === scopeTeamId &&
            !match.isDeleted
          ) {
            runlist = match;
          }
        }

        if (!runlist) {
          throw new Error("Could not resolve runlist `RL-1` (`New runlist`) in the current team.");
        }

        const run = await context.assets.runlists.runs.runNow({
          runlistId: runlist.id
        });

        uiIntents.push({
          kind: "asset.open",
          target: { kind: "asset-id", assetId: Number(runlist.id) },
          focus: true
        });

        const status = run.status ? String(run.status) : "started";

        return {
          summary: `Started runlist \`RL-1\` (\`New runlist\`) in the current team. Run status: \`${status}\`. The new run is now available in the runlist's execution history.`,
          uiIntents
        };
    })();
    if (__agentHandlerResult && typeof __agentHandlerResult === "object" && "summary" in __agentHandlerResult) {
        console.log("[agent.handler]", String((__agentHandlerResult as { summary?: unknown }).summary ?? ""));
    }
});
